import bpy, numpy as np
from collections import deque

def comps(i, mask_fn, min_size=40, ds=2):
    img=bpy.data.images[f'render_{i:04d}.png']; w,h=img.size
    arr=np.empty(w*h*4,dtype=np.float32); img.pixels.foreach_get(arr)
    a=arr.reshape(h,w,4)[:,:,:3]
    r,g,b=a[:,:,0],a[:,:,1],a[:,:,2]
    m=mask_fn(r,g,b)[::ds,::ds]
    H,Wd=m.shape; visited=np.zeros_like(m); out=[]
    for sy,sx in np.argwhere(m):
        if visited[sy,sx]: continue
        q=deque([(sy,sx)]); visited[sy,sx]=True
        n=0; x0=x1=sx; y0=y1=sy
        while q:
            y,x=q.popleft(); n+=1
            x0=min(x0,x);x1=max(x1,x);y0=min(y0,y);y1=max(y1,y)
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<Wd and m[ny,nx] and not visited[ny,nx]:
                    visited[ny,nx]=True; q.append((ny,nx))
        if n>=min_size: out.append((n*ds*ds,x0*ds,x1*ds,y0*ds,y1*ds))
    out.sort(reverse=True); return out

